#!/usr/bin/env node
// Generates src/styles/quiet-tokens.css from Quiet's tokens.json.
// Quiet is Noel's design system; see the quiet-design skill. Do not edit the output by hand.
//
// Usage: node tools/gen-quiet-tokens.mjs [path/to/tokens.json] [out.css]
// Defaults: ~/Documents/quiet-design/artifact/project/tokens.json -> src/styles/quiet-tokens.css

import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { homedir } from 'node:os'

const ACCENT = 'tide' // TBridge's skin (Noel, 24 Nov 2026)
const PALETTE = ['ember', 'tide', 'sky', 'moss', 'coral', 'plum', 'citron', 'mono']

const src = process.argv[2] ?? resolve(homedir(), 'Documents/quiet-design/artifact/project/tokens.json')
const out = process.argv[3] ?? resolve(import.meta.dirname, '../src/styles/quiet-tokens.css')
const tokens = JSON.parse(readFileSync(src, 'utf8'))

// Only the product's own accent family is kept; the other palette colours are not used here.
function isOtherPalette(name) {
  const base = name.replace(/-(hover|soft)$/, '')
  if (name === 'ember') return false // kept for the signature square (Quiet README, Signature)
  return PALETTE.includes(base) && base !== ACCENT
}

function colourValue(value) {
  const ref = /^\{(.+)\}$/.exec(value)
  return ref ? `var(--${ref[1]})` : value
}

function colourBlock(theme) {
  const lines = []
  for (const tok of tokens.color.tokens) {
    if (isOtherPalette(tok.name)) continue
    let value = tok.value[theme]
    if (tok.name === 'accent') value = `{${ACCENT}}`
    if (tok.name === 'accent-hover') value = `{${ACCENT}-hover}`
    if (tok.name === 'accent-soft') value = `{${ACCENT}-soft}`
    if (tok.name === 'info' || tok.name === 'info-soft') {
      // info points at sky; keep sky's values inline so the other palette entries can be dropped.
      const sky = tokens.color.tokens.find((t) => t.name === (tok.name === 'info' ? 'sky' : 'sky-soft'))
      value = sky.value[theme]
    }
    lines.push(`  --${tok.name}: ${colourValue(value)};`)
  }
  lines.push('  --sig: var(--ember);')
  for (const s of tokens.shadow.tokens) lines.push(`  --${s.name}: ${s.value[theme]};`)
  return lines.join('\n')
}

function staticBlock() {
  const lines = []
  lines.push(`  --font-sans: "Instrument Sans Variable", ${tokens.type.families.sans};`)
  lines.push(`  --font-mono: "JetBrains Mono Variable", ${tokens.type.families.mono};`)
  for (const group of ['spacing', 'radius', 'duration', 'easing', 'blur', 'opacity']) {
    for (const t of tokens[group].tokens) lines.push(`  --${t.name}: ${t.value};`)
  }
  return lines.join('\n')
}

const css = `/* Generated by tools/gen-quiet-tokens.mjs from Quiet tokens.json (version ${tokens.version}). Do not edit. */
/* Skin: accent = ${ACCENT}. */

:root {
${staticBlock()}
}

:root,
[data-theme="dark"] {
  color-scheme: dark;
${colourBlock('dark')}
}

[data-theme="light"] {
  color-scheme: light;
${colourBlock('light')}
}

@media (prefers-color-scheme: light) {
  :root:not([data-theme]) {
    color-scheme: light;
${colourBlock('light').replace(/^/gm, '  ')}
  }
}
`

mkdirSync(dirname(out), { recursive: true })
writeFileSync(out, css)
console.log(`Wrote ${out}`)
